PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE submissions (
  id TEXT PRIMARY KEY,
  lead_id INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  user_agent TEXT,
  reading_answers_json TEXT,
  listening_answers_json TEXT,
  writing_answers_json TEXT,
  speaking_meta_json TEXT,
  status TEXT NOT NULL DEFAULT 'new',
  examiner_note TEXT, reading_score INTEGER, reading_total INTEGER, reading_incorrect_json TEXT,
  FOREIGN KEY (lead_id) REFERENCES leads(id)
);
CREATE TABLE leads (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL,   email TEXT NOT NULL,   whatsapp TEXT,   consent INTEGER NOT NULL DEFAULT 0,   created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE submission_events (   id INTEGER PRIMARY KEY AUTOINCREMENT,   submission_id TEXT NOT NULL,   event_type TEXT NOT NULL,   payload_json TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (submission_id) REFERENCES submissions(id) );
CREATE TABLE listening_plays (   submission_id TEXT NOT NULL,   part INTEGER NOT NULL,   nonce TEXT NOT NULL,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   PRIMARY KEY (submission_id, part) );
DELETE FROM sqlite_sequence;
